<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{mentorAPI}from'../../api/mentor';import type{ApiKey}from'../../api/types';import{APIError}from'../../api/client';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import LoadingRegion from'../../components/LoadingRegion.vue';import{useLoadState}from'../../composables/useLoadState';import{useToast}from'../../composables/useToast';const rows=ref<ApiKey[]>([]),selected=ref<ApiKey|null>(null),comment=ref(''),query=ref(''),project=ref(''),error=ref(''),confirmReject=ref(false),toast=useToast(),loadState=useLoadState();const filtered=computed(()=>rows.value.filter(k=>(!query.value||`${k.applicant?.name} ${k.applicant?.email}`.toLowerCase().includes(query.value.toLowerCase()))&&(!project.value||k.project.id===project.value)));const projects=computed(()=>[...new Map(rows.value.map(k=>[k.project.id,k.project])).values()]);async function load(){await loadState.run(async()=>{try{rows.value=(await mentorAPI.reviews()).sort((a,b)=>a.created_at.localeCompare(b.created_at));if(selected.value&&!rows.value.some(v=>v.id===selected.value?.id))selected.value=null}catch(e){error.value=msg(e)}})}async function open(row:ApiKey){try{selected.value=await mentorAPI.review(row.id);comment.value=''}catch(e){error.value=msg(e)}}async function act(approve:boolean){if(!selected.value)return;if(!approve&&!comment.value.trim()){error.value='驳回必须填写原因';return}try{approve?await mentorAPI.approve(selected.value.id,comment.value||undefined):await mentorAPI.reject(selected.value.id,comment.value);toast.success(approve?'已通过初审':'已驳回申请');selected.value=null;confirmReject.value=false;comment.value='';await load();if(rows.value[0])await open(rows.value[0])}catch(e){if(e instanceof APIError&&e.code==='INVALID_STATE_TRANSITION'){selected.value=null;await load();toast.error('申请已由其他导师处理，队列已刷新')}else error.value=msg(e)}}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'}function refresh(){void load()};onMounted(()=>{void load();window.addEventListener('nebula:refresh',refresh)});onBeforeUnmount(()=>window.removeEventListener('nebula:refresh',refresh));</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">MENTOR</p><h1>审核密钥</h1><p class="muted">最早提交优先，仅显示你负责项目中的待初审申请。</p></div><button class="button secondary" @click="load">刷新</button></div><p v-if="error" class="error banner">{{error}}</p><section class="panel"><div class="grid two"><label>搜索申请人<input v-model="query" placeholder="姓名或邮箱"/></label><label>项目<select v-model="project"><option value="">全部项目</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div></section><LoadingRegion :initial-loading="loadState.initialLoading.value" :refreshing="loadState.refreshing.value" variant="split" label="正在加载审核队列"><div class="grid two" style="margin-top:20px"><section class="panel"><article v-for="key in filtered" :key="key.id" class="review-row"><div><strong>{{key.name}}</strong><p>{{key.applicant?.name}} · {{key.applicant?.email}}</p><p class="muted">{{key.project.name}} · {{key.models.length}} 个模型</p></div><button class="button primary" @click="open(key)">审核</button></article><div v-if="!filtered.length" class="empty">暂无待审核密钥</div></section><section class="panel"><template v-if="selected"><div class="row"><h2>{{selected.name}}</h2><StatusBadge :status="selected.status"/></div><p>{{selected.applicant?.name}}（{{selected.applicant?.email}}）</p><p>{{selected.organization.name}} · {{selected.project.name}}</p><p class="muted">提交于 {{new Date(selected.created_at).toLocaleString()}}</p><div v-for="model in selected.models" :key="model.id" class="list-row"><div><strong>{{model.display_name}}</strong><p class="muted">{{model.model_id}}</p></div><StatusBadge :status="model.status"/></div><label>审核意见<textarea v-model="comment" rows="4" placeholder="通过可留空；驳回必填"/></label><div class="actions"><button class="button danger" @click="confirmReject=true">驳回</button><button class="button primary" @click="act(true)">通过</button></div></template><div v-else class="empty">选择一条申请查看详情</div></section></div></LoadingRegion><AppDialog :open="confirmReject" title="确认驳回" @update:open="confirmReject=$event"><p>驳回后该申请进入终态，学生需重新提交新申请。</p><div class="actions"><button class="button danger" @click="act(false)">确认驳回</button></div></AppDialog></section></template>
